169	
170	// The HPC-036 sign-up payload: footer email (HPC-034) + modal names (HPC-035).
171	// Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
172	type PendingSignup = { email: string; firstName: string; lastName: string };
