  1	import React from 'react';
  2	import type { Meta, StoryObj } from '@storybook/react';
  3	import { expect, userEvent, within } from 'storybook/test';
  4	import { Footer } from './index';
  5	import { FOOTER_FIXTURE } from './contentfulFixture';
  6	
  7	const meta: Meta<typeof Footer> = {
  8	  title: 'Layout/Footer',
  9	  component: Footer,
 10	  parameters: {
 11	    layout: 'fullscreen',
 12	  },
 13	  args: {
 14	    data: FOOTER_FIXTURE,
 15	  },
 16	};
 17	
 18	export default meta;
 19	type Story = StoryObj<typeof Footer>;
 20	
 21	export const Default: Story = {
 22	  render: (args) => (
 23	    <div style={{ width: '100%' }}>
 24	      <Footer {...args} />
 25	    </div>
 26	  ),
 27	  // Asserts leavesTheSite's scheme branch. Security-adjacent: rel="noopener noreferrer" is what
 28	  // stops the storefront URL reaching WhatsApp in the Referer header, and the accessible-name
 29	  // suffix is WCAG 3.2.5. Nothing else in CI covered this — the behaviour was only ever verified
 30	  // by hand, which is exactly the kind of gap that survives a refactor invisibly.
 31	  play: async ({ canvasElement }) => {
 32	    const canvas = within(canvasElement);
 33	
 34	    // http(s) → new tab, hardened, and the name says so
 35	    const whatsApp = canvas.getByRole('link', { name: /whatsapp/i });
 36	    await expect(whatsApp).toHaveAttribute('target', '_blank');
 37	    await expect(whatsApp).toHaveAttribute('rel', 'noopener noreferrer');
 38	    await expect(whatsApp).toHaveAccessibleName(/opens in a new tab/i);
 39	
 40	    // tel:/mailto: hand off to the OS — a target would do nothing, so there must not be one
 41	    for (const name of [/call us/i, /email us/i]) {
 42	      const link = canvas.getByRole('link', { name });
 43	      await expect(link).not.toHaveAttribute('target');
 44	      await expect(link).not.toHaveAccessibleName(/opens in a new tab/i);
 45	    }
 46	  },
 47	};
 48	
 49	export const Subscribed: Story = {
 50	  args: {
 51	    initialSubscribed: true,
 52	  },
 53	  render: (args) => (
 54	    <div style={{ width: '100%' }}>
 55	      <Footer {...args} />
 56	    </div>
 57	  ),
 58	};
 59	
 60	export const SubscribeSubmit: Story = {
 61	  name: 'Subscribe — two-step flow (HPC-035, not shipped)',
 62	  // enableNameCapture is opt-in and off in production: SFCC-55 ships the placeholder path
 63	  // below. This story keeps the modal exercised so HPC-035 inherits working, covered code.
 64	  render: (args) => (
 65	    <div style={{ width: '100%' }}>
 66	      <Footer {...args} privacyPolicyHref="/privacy-policy" enableNameCapture />
 67	    </div>
 68	  ),
 69	  play: async ({ canvasElement }) => {
 70	    // Step 1 — email entry
 71	    const canvas = within(canvasElement);
 72	    const emailInput = canvas.getByRole('textbox', { name: /email/i });
 73	    await userEvent.type(emailInput, 'test@example.com');
 74	    const submitBtn = canvas.getByRole('button', { name: /subscribe/i });
 75	    await userEvent.click(submitBtn);
 76	
 77	    // Step 2 — modal should open. testing.md §Layer-2 requires within(canvasElement);
 78	    // portal exception: createPortal attaches the dialog to document.body, outside the
 79	    // Storybook canvas boundary, so within(document.body) is the required workaround.
 80	    const doc = within(document.body);
 81	    await expect(doc.getByRole('dialog')).toBeInTheDocument();
 82	    await userEvent.type(doc.getByRole('textbox', { name: /first name/i }), 'Jane');
 83	    await userEvent.type(doc.getByRole('textbox', { name: /last name/i }), 'Smith');
 84	    await userEvent.click(doc.getByRole('button', { name: /continue/i }));
 85	
 86	    // Modal closes. HPC-036 not yet landed → component shows the 'unavailable' message
 87	    // rather than false success. Update this assertion to /on the list/i once the Omneo
 88	    // POST is wired and setSubmitState('success') is reachable via a real API response.
 89	    await expect(doc.queryByRole('dialog')).not.toBeInTheDocument();
 90	    await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
 91	  },
 92	};
 93	
 94	export const SubscribeModalOpen: Story = {
 95	  name: 'Subscribe — modal open state (HPC-035, not shipped)',
 96	  render: (args) => (
 97	    <div style={{ width: '100%' }}>
 98	      <Footer {...args} privacyPolicyHref="/privacy-policy" enableNameCapture />
 99	    </div>
100	  ),
101	  // Covers the dialog mechanics now owned by useSubscribeModal: focus entry, Escape dismissal
102	  // and focus restore. Mutation-tested — breaking the setTimeout focus or the Escape branch
103	  // each fails this play. Before it existed, both mutations passed the whole Storybook suite,
104	  // so the hook extraction would have had no CI net at all.
105	  play: async ({ canvasElement }) => {
106	    const canvas = within(canvasElement);
107	    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
108	    const trigger = canvas.getByRole('button', { name: /subscribe/i });
109	    await userEvent.click(trigger);
110	
111	    // Portal renders outside canvasElement — testing.md §Layer-2 exception.
112	    const doc = within(document.body);
113	    const dialog = doc.getByRole('dialog');
114	    await expect(dialog).toBeInTheDocument();
115	    await expect(dialog).toHaveAttribute('aria-modal', 'true');
116	
117	    // Focus is moved into the dialog, onto the first field
118	    await expect(doc.getByRole('textbox', { name: /first name/i })).toHaveFocus();
119	
120	    // Escape dismisses it and focus returns to the control that opened it (WCAG 2.4.3)
121	    await userEvent.keyboard('{Escape}');
122	    await expect(doc.queryByRole('dialog')).not.toBeInTheDocument();
123	    await expect(trigger).toHaveFocus();
124	  },
125	};
126	
127	/**
128	 * Contact channels are optional per storefront, and a value arriving from Contentful may be
129	 * unsafe. Both cases fall through to a labelled, non-interactive span. Adding the placeholder
130	 * hrefs to the fixture made that branch unreachable from every other story, so it needs its own.
131	 */
132	const FIXTURE_DEGRADED_CHANNELS = {
133	  ...FOOTER_FIXTURE,
134	  fields: {
135	    ...FOOTER_FIXTURE.fields,
136	    // absent for this storefront
137	    phoneHref: undefined,
138	    // present but rejected by isSafeHref — must never reach an anchor
139	    whatsAppHref: 'javascript:alert(1)',
140	  },
141	};
142	
143	export const ContactChannelFallbacks: Story = {
144	  name: 'Contact channels — absent and unsafe',
145	  args: { data: FIXTURE_DEGRADED_CHANNELS },
146	  render: (args) => (
147	    <div style={{ width: '100%' }}>
148	      <Footer {...args} />
149	    </div>
150	  ),
151	  play: async ({ canvasElement }) => {
152	    const canvas = within(canvasElement);
153	
154	    // Absent and unsafe both render the icon as a labelled span: no href, no tab stop, so
155	    // nothing promises an action that cannot be performed (WCAG 2.4.4 / 3.2.4) — but the
156	    // channel stays perceivable rather than silently disappearing.
157	    for (const name of [/call us/i, /whatsapp/i]) {
158	      await expect(canvas.queryByRole('link', { name })).not.toBeInTheDocument();
159	      await expect(canvas.getByRole('img', { name })).toBeInTheDocument();
160	    }
161	
162	    // The safe channel is unaffected — degradation is per-channel, not all-or-nothing.
163	    await expect(canvas.getByRole('link', { name: /email us/i })).toHaveAttribute('href', 'mailto:care@zimmermann.com');
164	  },
165	};
166	
167	/**
168	 * The path SFCC-55 actually ships. Its AC scopes the Stay in Touch section to "an email input
169	 * field and submit button as a placeholder component" and defers the Omneo sign-up, so a valid
170	 * email resolves straight to the placeholder message with no name-capture modal.
171	 */
172	export const SubscribePlaceholder: Story = {
173	  name: 'Subscribe — placeholder path (SFCC-55 default)',
174	  render: (args) => (
175	    <div style={{ width: '100%' }}>
176	      <Footer {...args} />
177	    </div>
178	  ),
179	  play: async ({ canvasElement }) => {
180	    const canvas = within(canvasElement);
181	    const footer = canvasElement.querySelector('footer[role="contentinfo"]') as HTMLElement;
182	    const slot = footer.querySelector('[aria-live]') as HTMLElement;
183	    const heightBefore = footer.getBoundingClientRect().height;
184	    const slotBefore = slot.getBoundingClientRect().height;
185	
186	    await userEvent.type(canvas.getByRole('textbox', { name: /email/i }), 'test@example.com');
187	    await userEvent.click(canvas.getByRole('button', { name: /subscribe/i }));
188	
189	    // No modal — the default build does not collect names (HPC-035 is a separate story with no
190	    // design yet). Queried against document.body because the modal would portal outside canvas.
191	    await expect(within(document.body).queryByRole('dialog')).not.toBeInTheDocument();
192	
193	    // The shopper still gets honest feedback rather than a false success.
194	    await expect(canvas.getByText(/temporarily unavailable/i)).toBeInTheDocument();
195	    await expect(canvas.queryByText(/on the list/i)).not.toBeInTheDocument();
196	
197	    // No layout shift. The field and the message are different heights (45px vs 36px of text),
